from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
import hashlib
import json
from pathlib import Path
import re


class EntityType(str, Enum):
    CONVERSATION = "conversation"
    DECISION = "decision"
    PLAN = "plan"
    TOPIC = "topic"


CLAIM_PATTERN = re.compile(
    r"^\s*(?:#{1,6}\s*)?(?:\*\*)?(Decision|Plan|Topic)(?:\*\*)?\s*:\s*(.+?)\s*$",
    re.IGNORECASE,
)
ROLE_PATTERN = re.compile(r"^#{1,6}\s+(User|Assistant)\s*$", re.IGNORECASE)
STANDALONE_REPLACEMENT_PATTERN = re.compile(
    r"^\s*(?:This|That|The|It)(?:\s+(decision|plan))?\s+"
    r"(?:explicitly\s+)?replaces\s+(?:the\s+)?(?:decision\s+|plan\s+)?"
    r"(?:[\"“'](.+?)[\"”']|(.+?))\.?\s*$",
    re.IGNORECASE,
)
INLINE_REPLACEMENT_PATTERN = re.compile(
    r"^(.+?)\s+(?:explicitly\s+)?replaces\s+(?:the\s+)?"
    r"(?:decision\s+|plan\s+)?(?:[\"“'](.+?)[\"”']|(.+?))\.?\s*$",
    re.IGNORECASE,
)
KEY_LIKE_PATTERN = re.compile(
    r"\b((?:[a-z0-9]+[_-])*(?:api[_-]?)?"
    r"(?:key|token|secret|password|passwd|pwd)\s*[:=]\s*)"
    r"(?:\"[^\"\r\n]*\"|'[^'\r\n]*'|[^,;\r\n]+)",
    re.IGNORECASE,
)
TOKEN_LIKE_PATTERNS = (
    re.compile(r"\bsk-(?:proj-)?[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\b(?:ghp|gho|ghu|ghs|github_pat)_[A-Za-z0-9_]{16,}\b"),
    re.compile(r"(?i)\bBearer\s+[A-Za-z0-9._~-]{16,}"),
    re.compile(
        r"\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\."
        r"[A-Za-z0-9_-]{8,}\b"
    ),
)


@dataclass(frozen=True)
class ExtractedEntity:
    type: EntityType
    canonical_name: str
    line_number: int
    excerpt: str
    role: str | None


@dataclass(frozen=True)
class CodexMessage:
    role: str
    line_number: int
    text: str


@dataclass(frozen=True)
class SupersessionStatement:
    type: EntityType
    replacement_name: str
    replaced_name: str
    line_number: int
    excerpt: str
    role: str | None


@dataclass(frozen=True)
class CodexDocument:
    path: Path
    relative_path: str
    title: str
    occurred_at: str
    source_content_hash: str
